const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{once}=require('node:events');
const {app,BrowserWindow,session,protocol}=require('electron'),{ExtensionViewSessions}=require('../../electron/plugins/extensionViewSessions.cjs'),{VIEW_SCHEME,SCHEME,serveViewProtocol}=require('../../electron/plugins/extensionViewProtocol.cjs');
const config=JSON.parse(fs.readFileSync(process.argv.at(-1)));app.setPath('userData',path.join(config.directory,'user-data'));protocol.registerSchemesAsPrivileged([VIEW_SCHEME]);
const origin=SCHEME+'://state-probe',cacheUrl='https://state-probe.invalid/entry',windows=new Set();
app.whenReady().then(async()=>{
 // Keep the standalone app alive while every leased window is closed/cleared.
 windows.add(new BrowserWindow({show:false,webPreferences:{sandbox:true,nodeIntegration:false,contextIsolation:true}}));
 const pool=new ExtensionViewSessions(session,{limit:2}),a=await pool.acquire(),b=await pool.acquire(),checks=[];
 const open=async lease=>{const dispose=serveViewProtocol(lease.session,origin,new Map([['assets/view.html',Buffer.from('<!doctype html><h1>Session state fixture</h1>')]])),win=new BrowserWindow({show:false,webPreferences:{session:lease.session,sandbox:true,nodeIntegration:false,contextIsolation:true,backgroundThrottling:false}});windows.add(win);await win.loadURL(origin+'/assets/view.html');return {lease,win,dispose};};
 const seed=async(view,label)=>{await view.lease.session.cookies.set({url:'https://state-probe.invalid',name:'private-marker',value:label});await view.win.webContents.executeJavaScript(`(async()=>{const label=${JSON.stringify(label)};localStorage.setItem('private-marker',label);const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('private-state',1);r.onupgradeneeded=()=>r.result.createObjectStore('values');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});await new Promise((resolve,reject)=>{const tx=db.transaction('values','readwrite');tx.objectStore('values').put(label,'marker');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();const cache=await caches.open('private-state');await cache.put(${JSON.stringify(cacheUrl)},new Response(label));return true;})()`);};
 const read=async view=>{const cookies=await view.lease.session.cookies.get({name:'private-marker'}),state=await view.win.webContents.executeJavaScript(`(async()=>{const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('private-state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});let indexed=null;if(db.objectStoreNames.contains('values'))indexed=await new Promise((resolve,reject)=>{const r=db.transaction('values').objectStore('values').get('marker');r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error);});db.close();const cached=await caches.match(${JSON.stringify(cacheUrl)});return {local:localStorage.getItem('private-marker'),indexed,cached:cached?await cached.text():null};})()`);return {...state,cookies:cookies.map(cookie=>cookie.value)};};
 const release=view=>{view.dispose();const gone=once(view.win.webContents,'destroyed'),ready=view.lease.release(gone);view.win.destroy();windows.delete(view.win);return ready;};
 const first=await open(a),other=await open(b);await seed(first,'alpha');await seed(other,'beta');assert.deepEqual(await read(first),{local:'alpha',indexed:'alpha',cached:'alpha',cookies:['alpha']});assert.deepEqual(await read(other),{local:'beta',indexed:'beta',cached:'beta',cookies:['beta']});checks.push('live sessions isolate cookies, localStorage, IndexedDB and CacheStorage even at the same origin');
 await release(first);const recycled=await pool.acquire();assert.equal(recycled.session,a.session);const clean=await open(recycled);assert.deepEqual(await read(clean),{local:null,indexed:null,cached:null,cookies:[]});assert.deepEqual(await read(other),{local:'beta',indexed:'beta',cached:'beta',cookies:['beta']});checks.push('reused session is empty at its old origin and does not clear its live sibling');
 await release(clean);await release(other);for(let i=0;i<32;i++){const lease=await pool.acquire();await lease.release();}await pool.settle();assert.deepEqual(pool.snapshot(),{created:2,leased:0,cleaning:0,failed:0});checks.push('repeated leases create no additional native sessions');fs.writeFileSync(path.join(config.directory,'result.json'),JSON.stringify({ok:true,checks,pool:pool.snapshot(),userData:app.getPath('userData'),environment:{electron:process.versions.electron,node:process.version,platform:process.platform,arch:process.arch}},null,2));app.exit(0);
}).catch(error=>{for(const win of windows)try{win.destroy();}catch{}fs.writeFileSync(path.join(config.directory,'failure.json'),JSON.stringify({error:error.stack},null,2));console.error(error);app.exit(1);});
